func buildRenderBranch(obj *ConfigObj, branchObj *runtimeBranchObj, partialFlag bool) (*runtimeRenderNodeObj, bool, error) {
	resultNodeObj := &runtimeRenderNodeObj{
		KeyText:    branchObj.KeyText,
		UsageText:  branchObj.UsageText,
		BranchFlag: true,
		NodeObjArr: make([]*runtimeRenderNodeObj, 0, len(branchObj.EntryObjArr)),
	}
	includeFlag := false

	for _, entryObj := range branchObj.EntryObjArr {
		if entryObj.BranchFlag {
			childBranchObj := branchObj.BranchByKeyMap[entryObj.KeyText]
			if childBranchObj == nil {
				return nil, false, fmt.Errorf("render branch [%s]: missing branch metadata", entryObj.KeyText)
			}
			childNodeObj, childIncludeFlag, err := buildRenderBranch(obj, childBranchObj, partialFlag)
			if err != nil {
				return nil, false, err
			}
			if !childIncludeFlag && partialFlag {
				continue
			}
			resultNodeObj.NodeObjArr = append(resultNodeObj.NodeObjArr, childNodeObj)
			includeFlag = true
			continue
		}
		fieldMeta := branchObj.FieldByKeyMap[entryObj.KeyText]
		if fieldMeta == nil {
			return nil, false, fmt.Errorf("render field [%s]: missing field metadata", entryObj.KeyText)
		}
		if partialFlag && !obj.HasPath(fieldMeta.PathText) {
			continue
		}
		valueObj, err := fieldMeta.RenderValue(obj)
		if err != nil {
			return nil, false, fmt.Errorf("render field [%s]: %w", fieldMeta.PathText, err)
		}
		resultNodeObj.NodeObjArr = append(resultNodeObj.NodeObjArr, &runtimeRenderNodeObj{
			KeyText:   fieldMeta.KeyText,
			UsageText: fieldMeta.UsageText,
			ValueObj:  valueObj,
			KindObj:   fieldMeta.KindObj,
		})
		includeFlag = true
	}
	return resultNodeObj, includeFlag, nil
}

